const classes=[{id:'strength',name:'Strength foundations',coach:'Coach Aditya',time:'09:00',type:'STRENGTH',room:'Studio 01',booked:14,limit:18,joined:false},{id:'hiit',name:'The HIIT circuit',coach:'Coach Nisha',time:'10:30',type:'CONDITIONING',room:'Training floor',booked:11,limit:12,joined:false},{id:'mobility',name:'Mobility & reset',coach:'Coach Riya',time:'12:00',type:'RECOVERY',room:'Studio 02',booked:8,limit:16,joined:false}];
const revenue=[24000,28500,26100,32700,34900,40200,46800];const attendance=[42,58,51,73,65,89,76];
let view='overview',chartMode='week',aiReady=false,aiProvider='',aiBusy=false;let toastTimer;
const $=s=>document.querySelector(s);const initials=n=>n.split(' ').map(x=>x[0]).join('');const money=n=>'₹'+n.toLocaleString('en-IN');
function notify(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4200)}
function memberRows(list){return list.map(m=>`<tr><td><div class="person"><span class="avatar">${initials(m.name)}</span><div>${m.name}<small>PC-${String(m.id).padStart(3,'0')}</small></div></div></td><td>${m.plan}</td><td><span class="status ${m.renew<=7?'expiring':''}">${m.renew<=7?'Renews in '+m.renew+'d':'Active'}</span></td><td>${m.checked?m.time:m.time}</td></tr>`).join('')}
function table(list){return `<div class="table-wrap"><table><thead><tr><th>Member</th><th>Plan</th><th>Membership</th><th>Last visit</th></tr></thead><tbody>${memberRows(list)}</tbody></table></div>`}
function chart(){let values=chartMode==='week'?revenue:attendance;let max=chartMode==='week'?60000:100;let points=values.map((v,i)=>[40+i*76,190-v/max*165]);let line=points.map(p=>p.join(',')).join(' ');return `<div class="chart"><div class="chart-summary"><strong>${chartMode==='week'?money(values.reduce((a,b)=>a+b,0)):values.reduce((a,b)=>a+b,0)+' visits'}</strong><small>Last 7 completed days</small></div><svg viewBox="0 0 520 220" role="img" aria-label="${chartMode==='week'?'Revenue':'Attendance'} for 2 to 8 October: ${values.join(', ')}"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#d5ff5f" stop-opacity=".3"/><stop offset="100%" stop-color="#d5ff5f" stop-opacity="0"/></linearGradient></defs>${[25,80,135,190].map((y,i)=>`<line x1="40" x2="510" y1="${y}" y2="${y}" stroke="#35402e" stroke-dasharray="3 6"/><text x="0" y="${y+4}" fill="#909d85" font-size="11">${chartMode==='week'?['60k','40k','20k','0'][i]:['100','67','33','0'][i]}</text>`).join('')}<polygon points="40,190 ${line} 496,190" fill="url(#chart-fill)"/><polyline points="${line}" fill="none" stroke="#d5ff5f" stroke-width="3" stroke-linejoin="round"/>${points.map(p=>`<circle cx="${p[0]}" cy="${p[1]}" r="4" fill="#d5ff5f" stroke="#1b201b" stroke-width="2"/>`).join('')}</svg><div class="chart-labels">${['02 Oct','03','04','05','06','07','08 Oct'].map(x=>`<span>${x}</span>`).join('')}</div></div>`}
function classRows(){return classes.map(c=>`<div class="class-row"><div class="time">${c.time}<small>45 MIN</small></div><div class="class-info"><h3>${c.name}</h3><p>${c.coach} · ${c.booked}/${c.limit} spots</p><div class="capacity"><i style="width:${c.booked/c.limit*100}%"></i></div></div><button data-book="${c.id}" ${c.booked>=c.limit&&!c.joined?'disabled':''}>${c.joined?'Undo':'Book'}</button></div>`).join('')}
function overview(){const count=members.filter(m=>m.checked).length;return `<section class="metrics" aria-label="Club metrics"><article class="metric featured"><span class="metric-icon">◎</span><label>Active members</label><strong>${members.length}<span class="unit">sample members</span></strong><span class="trend">3 plans. One community.</span></article><article class="metric"><span class="metric-icon">₹</span><label>Revenue · last 7 days</label><strong>${money(revenue.reduce((a,b)=>a+b,0))}</strong><span class="trend">7 daily totals</span><span class="unit">02–08 October</span></article><article class="metric"><span class="metric-icon">↟</span><label>Today's check-ins</label><strong>${String(count).padStart(2,'0')}<span class="unit">of ${members.length} members</span></strong><span class="trend">${Math.round(count/members.length*100)}% checked in</span></article><article class="metric"><span class="metric-icon">◷</span><label>Renewals this week</label><strong>${members.filter(m=>m.renew<=7).length.toString().padStart(2,'0')}</strong><span class="trend orange">Worth a conversation</span><span class="unit">within 7 days</span></article></section><section class="grid"><article class="panel"><div class="panel-head"><div><h2>Club performance</h2><p class="sub">A little progress, every day.</p></div><div class="segmented" aria-label="Chart metric"><button data-chart="week" class="${chartMode==='week'?'active':''}" aria-pressed="${chartMode==='week'}">Revenue</button><button data-chart="visits" class="${chartMode==='visits'?'active':''}" aria-pressed="${chartMode==='visits'}">Visits</button></div></div>${chart()}</article><article class="panel ai-panel"><div class="panel-head ai-label"><span class="spark">✧</span> PULSE AI <em>${aiReady?'CONNECTED':'SETUP NEEDED'}</em></div><div class="ai-body"><h3>Know where to<br>focus your energy.</h3><p>Turn your club's numbers into a plan. Ask about renewals, attendance, or your next member conversation.</p><div class="ai-stat"><strong>03</strong><span>members renew this week.<br>Let’s give them a reason to stay.</span></div><button class="outline-btn" data-view="insights">Open AI assistant</button></div></article></section><section class="bottom-grid"><article class="panel"><div class="panel-head"><div><h2>On the floor</h2><p class="sub">Recent member check-ins</p></div><button class="text-btn" data-view="members">All members</button></div>${table(members.filter(m=>m.checked).sort((a,b)=>Number(b.time==='Just now')-Number(a.time==='Just now')).slice(0,4))}</article><article class="panel"><div class="panel-head"><div><h2>Up next</h2><p class="sub">Today's classes · 09 October</p></div><button class="text-btn" data-view="schedule">Schedule</button></div><div class="class-list">${classRows()}</div></article></section>`}
function memberView(){return `<section class="panel"><div class="panel-head"><div><h2>Your people, at a glance.</h2><p class="sub">12 sample members · membership and attendance</p></div></div><div class="toolbar"><input id="member-search" type="search" placeholder="Search members…" aria-label="Search members"><select id="member-filter" aria-label="Filter membership"><option value="all">All memberships</option><option value="renewing">Renewing this week</option><option value="checked">Checked in today</option></select></div><div id="member-results">${table(members)}</div></section>`}
function schedule(){return `<div class="ai-disclosure">Friday, 09 October · Booking adds one sample reservation. Use Undo to release it.</div><section class="schedule-grid">${classes.map(c=>`<article class="panel schedule-card"><span class="tag">${c.type}</span><div class="time">${c.time} <small>45 MINUTES · ${c.room}</small></div><h3>${c.name}</h3><p>${c.coach}<br>${c.booked} of ${c.limit} spots reserved</p><div class="capacity"><i style="width:${c.booked/c.limit*100}%"></i></div><button class="${c.joined?'outline-btn':'primary'}" data-book="${c.id}" ${c.booked>=c.limit&&!c.joined?'disabled':''}>${c.joined?'Undo reservation':c.booked>=c.limit?'Class full':'Book demo spot'}</button></article>`).join('')}</section>`}
function insights(){return `<section class="assistant-layout"><article class="panel chat"><div class="ai-label"><span class="spark">✧</span><h2>Your club's thinking partner.</h2></div><div class="ai-disclosure" style="margin-top:22px">${aiReady?'Live '+aiProvider+' assistant · Uses the sample club data shown in this dashboard.':'AI connection not configured yet. The interface is ready, but no AI-generated answers are available until a server key is connected.'}</div><p class="sub">Start with a question that moves your club forward.</p><div class="prompts"><button data-prompt="Which members need renewal follow-up this week?">Renewal priorities</button><button data-prompt="Summarize attendance and suggest two ways to improve it.">Attendance insights</button><button data-prompt="Draft a friendly renewal message for Kabir. Do not send it.">Draft a follow-up</button></div><div id="answer" class="answer" role="status">Your next move starts with a good question.</div><form class="chat-form" id="chat-form"><input id="question" maxlength="1000" placeholder="Ask about your club…" aria-label="Question for Pulse AI" required><button class="primary" id="ask-button" type="submit">Ask Pulse AI</button></form></article><aside class="panel insight-side"><h3>Grounded in your club.</h3><p><strong>Memberships</strong><br>12 sample records, plan types, and renewal dates.</p><p><strong>Club activity</strong><br>Recent visits and today's check-ins.</p><p><strong>Revenue & classes</strong><br>Seven daily totals and three scheduled classes.</p><p>AI can make mistakes. Review any recommendation before acting. Messages are drafted here, never sent.</p></aside></section>`}
function render(){const titles={overview:['Your club. In motion.','A clear view of the people, progress, and energy behind your club.','Overview'],members:['Every member matters.','Know who’s showing up, and who could use a little nudge.','Members'],schedule:['Make room for movement.','A strong schedule. A stronger community.','Class schedule'],insights:['Less guesswork. More progress.','Ask your club’s numbers what comes next.','Pulse AI']};const t=titles[view];$('#page-title').textContent=t[0];$('#page-subtitle').textContent=t[1];$('#crumb').textContent=t[2];document.querySelectorAll('nav button').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-current',b.dataset.view===view?'page':'false')});$('#surface').innerHTML=({overview,members:memberView,schedule,insights}[view])();}
function navigate(v){if(!['overview','members','schedule','insights'].includes(v))return;view=v;location.hash=v;render()}
function book(id){let c=classes.find(x=>x.id===id);if(!c)throw Error('Unknown class');if(!c.joined&&c.booked>=c.limit)throw Error('Class is full');c.joined=!c.joined;c.booked+=c.joined?1:-1;render();notify(c.joined?'Demo spot reserved in '+c.name:'Demo reservation removed');return {class:c.name,reserved:c.joined,spots:c.booked}}
function checkin(id){let m=members.find(x=>x.id===Number(id));if(!m)throw Error('Choose a member');if(m.checked)throw Error('This member is already checked in today.');m.checked=true;m.time='Just now';m.visits++;render();notify(m.name+' checked in · demo visit');return {member:m.name,checkedIn:true}}
function snapshot(){return {referenceDate:'2026-10-09',currency:'INR',members:members.map(({id,name,plan,renew,visits,checked})=>({id,name,plan,renewalInDays:renew,visitsThisMonth:visits,checkedInToday:checked})),dailyRevenue:revenue,dailyAttendance:attendance,period:'2026-10-02 to 2026-10-08',classes:classes.map(({name,coach,time,booked,limit})=>({name,coach,time,booked,capacity:limit}))}}
async function ask(question){if(aiBusy)return; if(!question.trim())return;const answer=$('#answer');if(!aiReady){answer.textContent='Pulse AI is not connected yet. Add the AI service key to the server configuration to enable live answers.';return}aiBusy=true;$('#ask-button').disabled=true;answer.textContent='Reviewing your club data…';try{const response=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question,snapshot:snapshot()})});const result=await response.json();if(!response.ok)throw Error(result.error||'The assistant could not respond. Please try again.');if(!result.answer)throw Error('The assistant returned an empty response.');if($('#answer'))$('#answer').textContent=result.answer;}catch(e){if($('#answer'))$('#answer').textContent=e.message;}finally{aiBusy=false;if($('#ask-button'))$('#ask-button').disabled=false}}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.view)navigate(b.dataset.view);if(b.dataset.chart){chartMode=b.dataset.chart;render()}if(b.dataset.book){try{book(b.dataset.book)}catch(err){notify(err.message)}}if(b.dataset.prompt){$('#question').value=b.dataset.prompt;ask(b.dataset.prompt)}});
document.addEventListener('input',e=>{if(e.target.id==='member-search')filterMembers()});document.addEventListener('change',e=>{if(e.target.id==='member-filter')filterMembers()});function filterMembers(){let q=$('#member-search').value.toLowerCase(),f=$('#member-filter').value;let result=members.filter(m=>m.name.toLowerCase().includes(q)&&(f==='all'||f==='renewing'&&m.renew<=7||f==='checked'&&m.checked));$('#member-results').innerHTML=result.length?table(result):'<p class="empty">No members match your search.</p>'}
$('#checkin-open').onclick=()=>{$('#member-select').innerHTML='<option value="">Select a member</option>'+members.map(m=>`<option value="${m.id}" ${m.checked?'disabled':''}>${m.name}${m.checked?' — already checked in':''}</option>`).join('');$('#checkin-error').textContent='';$('#checkin-dialog').showModal()};$('#close-dialog').onclick=()=>$('#checkin-dialog').close();$('#checkin-form').onsubmit=e=>{e.preventDefault();try{checkin($('#member-select').value);$('#checkin-dialog').close()}catch(err){$('#checkin-error').textContent=err.message}};document.addEventListener('submit',e=>{if(e.target.id==='chat-form'){e.preventDefault();ask($('#question').value)}});window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(['overview','members','schedule','insights'].includes(v)&&v!==view){view=v;render()}});view=['overview','members','schedule','insights'].includes(location.hash.slice(1))?location.hash.slice(1):'overview';render();
fetch('/api/status').then(r=>r.ok?r.json():{}).then(s=>{aiReady=Boolean(s.configured);aiProvider=s.provider||'AI';document.querySelector('nav em').textContent=aiReady?'LIVE':'SETUP';if(view==='overview'||view==='insights')render()}).catch(()=>{});
if(document.modelContext?.registerTool){const life=new AbortController();window.addEventListener('pagehide',()=>life.abort(),{once:true});for(const tool of [{name:'check_in_demo_member',description:'Record a sample member check-in in the visible gym dashboard. No real gym record is changed.',inputSchema:{type:'object',properties:{memberId:{type:'integer',minimum:1,maximum:12}},required:['memberId'],additionalProperties:false},execute:input=>{if(!input||!Number.isInteger(input.memberId))throw Error('memberId must be an integer');return checkin(input.memberId)}},{name:'read_gym_demo_snapshot',description:'Read the sample member, attendance, class and revenue data currently shown in the gym dashboard.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>snapshot()}])Promise.resolve(document.modelContext.registerTool(tool,{signal:life.signal})).catch(()=>{});}
